export function PinchZoom({
  scale = "{{scale}}",
  accent = "{{accent}}",
  showAltControls = {{showAltControls}},
}) {
  const factor = { "100": 1, "150": 1.5, "200": 2 }[scale];
  return (
    <div style={{ width: 280, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ position: "relative", height: 110, borderRadius: 12, background: "#24143010", display: "grid", placeItems: "center", overflow: "hidden" }}>
        <svg width="64" height="64" viewBox="0 0 64 64" aria-hidden="true" style={{ transform: "scale(" + factor + ")", transition: "transform .2s" }}>
          <rect width="64" height="64" rx="8" fill={accent} /><circle cx="24" cy="26" r="7" fill="#FAF7F2" /><path d="M8 50l16-16 10 8 12-14 10 22z" fill="#FAF7F2" />
        </svg>
      </div>
      <p style={{ margin: "10px 0 0", fontSize: 12, color: "#241430aa" }}>Two-finger pinch to zoom &mdash; <strong>{scale}%</strong>. No touchscreen? Use Ctrl/Cmd + scroll, or the buttons below.</p>
      {showAltControls && <div style={{ marginTop: 10, display: "flex", gap: 6 }}>
        <button type="button" aria-label="Zoom out" style={{ width: 30, height: 30, borderRadius: 7, border: "1.5px solid " + accent, background: "#FAF7F2", fontSize: 16, cursor: "pointer" }}>&minus;</button>
        <button type="button" aria-label="Zoom in" style={{ width: 30, height: 30, borderRadius: 7, border: "1.5px solid " + accent, background: "#FAF7F2", fontSize: 16, cursor: "pointer" }}>+</button>
      </div>}
    </div>
  );
}
